function v3_verify(out)
files=dir(fullfile(out,'E*','cases','*','sim_output.mat'));rows={};for k=1:numel(files)
folder=files(k).folder;s=jsondecode(fileread(fullfile(folder,'case_config.json')));if ~ismember(s.group,{'E1','E2','E3','E4'}),continue;end
d=load(fullfile(folder,'sim_output.mat'));r=d.r;v3_analyze(r,s,folder);v3_actuator_export(r,s,folder);t=r.states.Time(:);x=squeeze(r.states.Data);bank=load(fullfile(folder,'reference_bank.mat'));ref=interp1(bank.time(:),squeeze(bank.q_ref(:,1,:))',t,'linear','extrap');ref=ref./sqrt(sum(ref.^2,2));q=eul2quat(x(:,[3 2 1]));error_deg=rad2deg(2*acos(min(1,abs(sum(q.*ref,2)))));saved=jsondecode(fileread(fullfile(folder,'metrics.json')));rmse=sqrt(mean(error_deg.^2));peak=max(error_deg);ok=abs(rmse-saved.rmse_partial_deg)<1e-7 && abs(peak-saved.peak_attitude_error_deg)<1e-7;
build=jsondecode(fileread(fullfile(folder,'build_config.json')));ok=ok && isa(r,'Simulink.SimulationOutput') && build.sqp_limit==4 && build.dt_ctrl==.2 && build.inner_period==.02 && build.fixed_step==.001 && size(x,2)==6+4*logical(s.cmg) && strcmp(paper_hash(build.model_path),build.model_sha256) && strcmp(paper_hash(fullfile(folder,'reference_bank.mat')),build.bank_sha256);
detail=v3_detail_metrics(r,s,folder);ok=ok && detail.physical_bounds_pass && detail.truth_period_pass && detail.upper_period_pass && detail.inner_period_pass;
statuspath=fullfile(folder,'run_status.json');st=jsondecode(fileread(statuspath));if ~strcmp(st.status,saved.status),st.previous_analysis_status=st.status;end;st.status=saved.status;st.error=saved.error_message;st.actual_end_s=saved.actual_end_s;st.independent_reanalysis=true;paper_json(statuspath,st);
rows{end+1}=struct('id',s.id,'group',s.group,'independent_rmse_deg',rmse,'saved_rmse_deg',saved.rmse_partial_deg,'independent_peak_deg',peak,'physical_bounds_pass',detail.physical_bounds_pass,'truth_1ms_pass',detail.truth_period_pass,'upper_200ms_pass',detail.upper_period_pass,'inner_20ms_pass',detail.inner_period_pass,'passed',ok);fprintf('V3_VERIFY %d %s pass=%d\n',numel(rows),s.id,ok);
end
if ~isempty(rows),T=struct2table([rows{:}],'AsArray',true);writetable(T,fullfile(out,'tables','independent_reanalysis.csv'));allpass=all(T.passed);else,allpass=false;end
pairpass=true;paircount=0;files=dir(fullfile(out,'E1','cases','*_A','reference_bank.mat'));for k=1:numel(files),id=files(k).folder;other=[id(1:end-1) 'B'];if ~isfile(fullfile(other,'reference_bank.mat')),pairpass=false;continue;end;a=load(fullfile(id,'reference_bank.mat'));b=load(fullfile(other,'reference_bank.mat'));for key={'time','q_ref','omega_ref','tau_d'},field=key{1};pairpass=pairpass && max(abs(a.(field)(:)-b.(field)(:)))<1e-10;end;pairpass=pairpass && max(abs(a.x0(1:7)-b.x0(1:7)))<1e-10;paircount=paircount+1;end
% L/S/Z current-node references and current physical disturbance must match appropriately.
migrationpass=false;folder=fullfile(out,'E3','cases');if isfile(fullfile(folder,'V3_L','reference_bank.mat')) && isfile(fullfile(folder,'V3_S','reference_bank.mat')) && isfile(fullfile(folder,'V3_Z','reference_bank.mat'))
a=load(fullfile(folder,'V3_L','reference_bank.mat'));b=load(fullfile(folder,'V3_S','reference_bank.mat'));z=load(fullfile(folder,'V3_Z','reference_bank.mat'));migrationpass=max(abs(a.q_ref(:,1,:)-b.q_ref(:,1,:)),[],'all')<1e-10 && max(abs(a.omega_ref(:,1,:)-b.omega_ref(:,1,:)),[],'all')<1e-10 && max(abs(a.tau_d(:,1,:)-z.tau_d(:,1,:)),[],'all')<1e-10 && max(abs(b.tau_d(:,1,:)-z.tau_d(:,1,:)),[],'all')<1e-10 && max(abs(z.omega_ref),[],'all')==0 && max(abs(z.q_ref-z.q_ref(:,1,1)),[],'all')<1e-10 && isequal(a.x0,b.x0,z.x0);
end
% All 27 E4 triplets share the exact current physical bank fields and frozen PID version.
e4pass=true;triplets=0;pidpath=fullfile(out,'calibration','pid_frozen.json');if isfile(pidpath),pidsha=paper_hash(pidpath);else,pidsha='missing';end
for amp=[1 3 5],for f=[.02 .04 .06 .08 .1 .12 .15 .18 .2],prefix=sprintf('V4_%03d_%03d',round(amp*10),round(f*1000));banks=cell(1,3);for method=1:3,folder=fullfile(out,'E4','cases',sprintf('%s_%d',prefix,method));if isfile(fullfile(folder,'reference_bank.mat')),banks{method}=load(fullfile(folder,'reference_bank.mat'));if method==2,build=jsondecode(fileread(fullfile(folder,'build_config.json')));cfg=jsondecode(fileread(fullfile(folder,'case_config.json')));e4pass=e4pass && strcmp(build.frozen_pid_sha256,pidsha) && ~cfg.pid.unload && strcmp(build.upper_function,'v3_pid_sfun');end;else,e4pass=false;end;end;if all(~cellfun(@isempty,banks)),for method=2:3,for key={'time','q_ref','omega_ref','tau_d','x0'},field=key{1};e4pass=e4pass && max(abs(banks{1}.(field)(:)-banks{method}.(field)(:)))<1e-10;end;end;triplets=triplets+1;end;end,end
paper_json(fullfile(out,'reports','independent_verification.json'),struct('cases_checked',numel(rows),'reanalysis_pass',allpass,'E1_pairs',paircount,'E1_pairs_equal',pairpass && paircount==72,'E3_references_consistent',migrationpass,'E4_triplets',triplets,'E4_conditions_and_PID_frozen',e4pass && triplets==27));
end
